              { kind: "text", selector: '[data-testid="claim"]', nth: 0, value: "CL-341 Casa Verde Foods 268k \xB7 open" },
              { kind: "text", selector: '[data-testid="claim"]', nth: 3, value: "CL-330 Orinoco Rail 953k \xB7 closed" }
