        answers: [0, 1, 2],
        why: "`$watch(expr, cb, { immediate, deep })` \u2014 one property, both values, optional depth. `x-effect` remains the tool for multi-value dependencies.",
        distractors: { 3: "An effect tracks *every* reactive read; a watch tracks one expression." }
